public class FluidBuilder extends BuilderBase<FluidType> {
	public transient ResourceLocation stillTexture;
	public transient ResourceLocation flowingTexture;
	public transient ResourceLocation bucketItem;
	public transient int density;
	public transient int viscosity;
	public transient int temperature;
	public transient int lightLevel;
	public transient int color;
	public transient Map<String, Component> lang;
	public transient boolean gaseous;

	public FluidBuilder(ResourceLocation id) {
		super(id);
		this.density = 1000;
		this.viscosity = 1000;
		this.temperature = 300;
		this.lightLevel = 0;
		this.color = 0xFFFFFFFF;
		this.lang = new HashMap<>();
		this.gaseous = false;
	}

	@Info("Sets the fluid's density.")
	public FluidBuilder density(int v) {
		density = v;
		return this;
	}

	@Info("Sets the fluid's viscosity.")
	public FluidBuilder viscosity(int v) {
		viscosity = v;
		return this;
	}

	@Info("Sets the fluid's temperature.")
	public FluidBuilder temperature(int v) {
		temperature = v;
		return this;
	}

	@Info("Sets the fluid's light level.")
	public FluidBuilder lightLevel(int v) {
		lightLevel = v;
		return this;
	}
